/**
 * PatrolIntent - Waypoint patrol behavior
 *
 * Patrols between waypoints in sequence, optionally looping.
 * Low priority intent that activates when no threats are present.
 *
 * **Usage**
 *
 * ```js
 * body.ai.addIntent(new PatrolIntent({
 *   waypoints: [
 *     { x: 0, y: 0, z: 0 },
 *     { x: 10, y: 0, z: 0 },
 *     { x: 10, y: 0, z: 10 },
 *     { x: 0, y: 0, z: 10 }
 *   ],
 *   waitTime: 2.0,    // Wait at each waypoint
 *   loop: true,       // Loop back to start
 *   priority: 20      // Low priority
 * }));
 * ```
 *
 * **Events Emitted**
 *
 * | Event | When | Payload |
 * |-------|------|---------|
 * | `patrol` | Patrol starts (intent activates) | `{ waypointIndex, waypoint }` |
 * | `waypointReached` | Arrived at a waypoint | `{ waypointIndex, waypoint, isLast }` |
 *
 * ```js
 * body.ai.addEventListener('patrol', (event) => {
 *   console.log('Started patrolling at waypoint', event.waypointIndex);
 * });
 *
 * body.ai.addEventListener('waypointReached', (event) => {
 *   console.log('Arrived at waypoint', event.waypointIndex);
 * });
 * ```
 *
 * @module @three-blocks/pro/ai/PatrolIntent
 * @class PatrolIntent
 * @extends Intent
 * @short Waypoint patrol behavior
 * @category AI
 * @tags AI, Intent, Patrol, Movement, Events
 */
export class PatrolIntent extends Intent {
    /**
     * Events this intent can emit.
     * @type {string[]}
     * @static
     */
    static events: string[];
    /**
     * Create a new PatrolIntent.
     *
     * @param {Object} [config] - Configuration options.
     * @param {Array<{x: number, y: number, z: number}>} [config.waypoints=[]] - Patrol waypoints.
     * @param {number} [config.waitTime=1.0] - Time to wait at each waypoint.
     * @param {boolean} [config.loop=true] - Loop back to first waypoint.
     * @param {number} [config.arrivalRadius=1.5] - Distance to consider arrived.
     * @param {number} [config.skipUnreachableTime=3.0] - Time before skipping unreachable waypoint.
     * @param {number} [config.priority=20] - Selection priority.
     */
    constructor(config?: {
        waypoints?: Array<{
            x: number;
            y: number;
            z: number;
        }>;
        waitTime?: number;
        loop?: boolean;
        arrivalRadius?: number;
        skipUnreachableTime?: number;
        priority?: number;
    });
    /**
     * Patrol waypoints.
     * @type {Array<{x: number, y: number, z: number}>}
     * @private
     */
    private _waypoints;
    /**
     * Time to wait at each waypoint.
     * @type {number}
     * @private
     */
    private _waitTime;
    /**
     * Whether to loop back to start.
     * @type {boolean}
     * @private
     */
    private _loop;
    /**
     * Distance to consider arrived.
     * @type {number}
     * @private
     */
    private _arrivalRadius;
    /**
     * Time before skipping an unreachable waypoint.
     * @type {number}
     * @private
     */
    private _skipUnreachableTime;
    /**
     * Current waypoint index.
     * @type {number}
     * @private
     */
    private _currentIndex;
    /**
     * Time waiting at current waypoint.
     * @type {number}
     * @private
     */
    private _waitTimer;
    /**
     * Whether currently waiting.
     * @type {boolean}
     * @private
     */
    private _isWaiting;
    /**
     * Direction of patrol (1 = forward, -1 = reverse for ping-pong).
     * @type {number}
     * @private
     */
    private _direction;
    /**
     * Time spent trying to reach current waypoint (for detecting unreachable).
     * @type {number}
     * @private
     */
    private _stuckTimer;
    /**
     * Last known distance to waypoint (for detecting progress).
     * @type {number}
     * @private
     */
    private _lastDistSq;
    /**
     * Set waypoints.
     *
     * @param {Array<{x: number, y: number, z: number}>} value - Waypoints array.
     */
    set waypoints(value: Array<{
        x: number;
        y: number;
        z: number;
    }>);
    /**
     * Get waypoints.
     *
     * @returns {Array<{x: number, y: number, z: number}>} Waypoints array.
     */
    get waypoints(): Array<{
        x: number;
        y: number;
        z: number;
    }>;
    /**
     * Advance to next waypoint.
     *
     * @private
     */
    private _advanceWaypoint;
    /**
     * Configure patrol parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {PatrolIntent} This instance for chaining.
     */
    set(config: any): PatrolIntent;
    /**
     * Reset patrol state.
     */
    reset(): void;
}
import { Intent } from './Intent.js';
